   private ThirdPointAllocationQueryResult getInfeasibleByConfig(
       ThirdPointAllocationQueryParam pointCapacityQueryParam) {
       PointRadioServiceExpectation serviceExpectation = pointCapacityQueryParam.getIntentExpectations().getFirst();
       GeoCoordinate geoCoordinate = serviceExpectation.getExpectationObject()
           .getObjectContexts()
           .getFirst()
           .getContextValueRange();
       LOGGER.info("geoCoordinate.getLongitude() + \"#\" + geoCoordinate.getLatitude(): {}",
           geoCoordinate.getLongitude() + "#" + geoCoordinate.getLatitude());
       String allocConfigValueByName = dataDbMapper.getAllocConfigValueByName(
           geoCoordinate.getLongitude() + "#" + geoCoordinate.getLatitude());
       LOGGER.info("allocConfigValueByName: {}", allocConfigValueByName);
       if (StringUtils.isBlank(allocConfigValueByName)) {
           return null;
       }
       String[] configs = allocConfigValueByName.split("#");
       return buildPointAllocResult(configs[0], configs.length > 1 ? configs[1] : null);
   }

   private ThirdPointAllocationQueryResult buildPointAllocResult(String feasibilityCheckResult,
       String infeasibilityReasons) {
       ThirdPointAllocationQueryResult thirdPointAllocationQueryResult = new ThirdPointAllocationQueryResult();
       thirdPointAllocationQueryResult.setIntentFeasibilityCheckReport(
           new PointExpectationExplorationResult(feasibilityCheckResult, infeasibilityReasons));
       return thirdPointAllocationQueryResult;
   }
   ```

